# autotune XBLOCK in {1024,2048,4096}, num_warps in {4,8}
@triton.autotune(configs=[Config({'XBLOCK':1024},num_warps=4), ...], key=['xnumel'])
@triton.jit
def kernel(in_out_ptr0, in_ptr0, xnumel, XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    xindex = xoffset + tl.arange(0, XBLOCK)[:]
    xmask = xindex < xnumel  # now masked
    x0 = xindex % 16384
    tmp0 = tl.load(in_ptr0 + x0, xmask, eviction_policy='evict_last')
    tmp1 = tl.load(in_out_ptr0 + xindex, xmask)
    tl.store(in_out_ptr0 + xindex, tanh(tmp0 + tmp1), xmask)

